import ast
import builtins
import glob
import os
import symtable
import sys

ROOT = "/app/tally/reports"
LAYER = {"errors": 0, "tables": 0, "state": 0, "system": 0, "formatting": 1, "model": 1, "loading": 2,
         "aggregate": 3, "renderers": 4, "cli": 5, "__init__": 6}
mods = {}
for fn in glob.glob(ROOT + "/**/*.py", recursive=True):
    rel = os.path.relpath(fn, ROOT)[:-3].split(os.sep)
    if rel[-1] == "__init__" and len(rel) > 1:
        rel = rel[:-1]
        key = ("pkg",) + tuple(rel)
        name = ".".join(rel)
    else:
        name = ".".join(rel)
    mods[name] = fn
modnames = set(mods)
bad = False
graph = {}


def layer(name):
    return LAYER[name.split(".")[0]]


# sizes
for n, fn in mods.items():
    cnt = len(open(fn, encoding="utf-8").read().split("\n")) - 1
    if cnt > 400:
        print("TOO LONG", fn, cnt); bad = True

for name, fn in mods.items():
    tree = ast.parse(open(fn, encoding="utf-8").read())
    is_pkg = os.path.basename(fn) == "__init__.py"
    pkg_parts = name.split(".") if is_pkg else name.split(".")[:-1]
    if name == "__init__":
        pkg_parts = []
    edges = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for a in node.names:
                if a.name.startswith("tally"):
                    print("ABSOLUTE tally import", name, a.name); bad = True
                if a.name in ("importlib",):
                    print("importlib", name); bad = True
        elif isinstance(node, ast.ImportFrom):
            if node.level == 0:
                if node.module and node.module.split(".")[0] == "tally":
                    print("ABSOLUTE tally import", name, node.module); bad = True
                if node.module == "importlib":
                    print("importlib", name); bad = True
                continue
            base = pkg_parts[: len(pkg_parts) - (node.level - 1)] if node.level > 1 else pkg_parts
            if node.level - 1 > len(pkg_parts):
                print("escapes package", name); bad = True
            basename = ".".join(base + (node.module.split(".") if node.module else []))
            for a in node.names:
                cand = (basename + "." + a.name).strip(".")
                if basename == "" and a.name in modnames:
                    edges.add(a.name)
                elif cand in modnames:
                    edges.add(cand)
                elif basename in modnames:
                    edges.add(basename)
                elif basename == "":
                    edges.add("__init__")
                else:
                    print("unresolved", name, basename, a.name); bad = True
        elif isinstance(node, ast.Name) and node.id in ("__import__",):
            print("__import__", name); bad = True
    graph[name] = edges
    for e in edges:
        if layer(e) > layer(name):
            print("LAYER VIOLATION", name, "->", e); bad = True
# cycles
color = {}


def dfs(n, stack):
    global bad
    color[n] = 1
    for e in graph.get(n, ()):
        if e == n:
            print("self import", n); bad = True
        if color.get(e) == 1:
            print("CYCLE", stack + [n, e]); bad = True
        elif e not in color:
            dfs(e, stack + [n])
    color[n] = 2


for n in graph:
    if n not in color:
        dfs(n, [])

# undefined globals via symtable
for name, fn in mods.items():
    src = open(fn, encoding="utf-8").read()
    top = symtable.symtable(src, fn, "exec")
    defined = set(top.get_identifiers()) - {s.get_name() for s in top.get_symbols() if not (s.is_assigned() or s.is_imported() or s.is_namespace())}
    defined |= set(dir(builtins))

    def walk(t):
        for s in t.get_symbols():
            if s.is_global() and s.is_referenced() and s.get_name() not in defined:
                print("UNDEFINED GLOBAL", name, t.get_name(), s.get_name()); globals()["bad"] = True
        for c in t.get_children():
            walk(c)
    for s in top.get_symbols():
        if s.is_referenced() and not (s.is_assigned() or s.is_imported() or s.is_namespace()) and s.get_name() not in defined:
            print("UNDEFINED", name, s.get_name()); bad = True
    for c in top.get_children():
        walk(c)

# module-state rule: rebound variables
for name, fn in mods.items():
    tree = ast.parse(open(fn, encoding="utf-8").read())
    for node in ast.walk(tree):
        if isinstance(node, ast.Global):
            print("global in", name, node.names)

# __init__ content
tree = ast.parse(open(ROOT + "/__init__.py", encoding="utf-8").read())
for i, node in enumerate(tree.body):
    ok = isinstance(node, (ast.ImportFrom, ast.Import)) or (i == 0 and isinstance(node, ast.Expr) and isinstance(node.value, ast.Constant)) or (isinstance(node, ast.Assign) and node.targets[0].id == "__all__")
    if not ok:
        print("BAD __init__ statement", ast.dump(node)[:100]); bad = True
print("BAD" if bad else "structure OK", len(mods), "modules")

