import glob
import os
import symtable

ROOT = "/app/tally/reports"
LAYER = {"errors": 0, "tables": 0, "state": 0, "system": 0, "formatting": 1, "model": 1, "loading": 2,
         "aggregate": 3, "renderers": 4, "cli": 5, "__init__": 6}
mods = {}
for fn in glob.glob(ROOT + "/**/*.py", recursive=True):
    rel = os.path.relpath(fn, ROOT)[:-3].split(os.sep)
    if rel[-1] == "__init__" and len(rel) > 1:
        rel = rel[:-1]
    mods[".".join(rel)] = fn
modnames = set(mods)
bad = False
graph = {}


def layer(name):
    return LAYER[name.split(".")[0]]


for n, fn in mods.items():
    cnt = len(open(fn, encoding="utf-8").read().split("\n")) - 1
    if cnt > 400:
        print("TOO LONG", fn, cnt)
        bad = True

for name, fn in mods.items():
    tree = ast.parse(open(fn, encoding="utf-8").read())
    is_pkg = os.path.basename(fn) == "__init__.py"
    if name == "__init__":
        pkg_parts = []
    elif is_pkg:
        pkg_parts = name.split(".")
    else:
        pkg_parts = name.split(".")[:-1]
    edges = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for a in node.names:
                if a.name.startswith("tally") or a.name == "importlib":
                    print("BAD import", name, a.name)
                    bad = True
        elif isinstance(node, ast.ImportFrom):
            if node.level == 0:
                if node.module and node.module.split(".")[0] in ("tally", "importlib"):
                    print("BAD import", name, node.module)
                    bad = True
                continue
            base = pkg_parts[: len(pkg_parts) - (node.level - 1)]
            basename = ".".join(base + (node.module.split(".") if node.module else []))
            for a in node.names:
                cand = (basename + "." + a.name).strip(".")
                if cand in modnames:
                    edges.add(cand)
                elif basename in modnames:
                    edges.add(basename)
                elif basename == "":
                    edges.add("__init__")
                else:
                    print("unresolved", name, basename, a.name)
                    bad = True
        elif isinstance(node, ast.Name) and node.id == "__import__":
            print("__import__", name)
            bad = True
    graph[name] = edges
    for e in edges:
        if layer(e) > layer(name):
            print("LAYER VIOLATION", name, "->", e)
            bad = True

color = {}


def dfs(n, stack):
    global bad
    color[n] = 1
    for e in graph.get(n, ()):
        if color.get(e) == 1:
            print("CYCLE", stack + [n, e])
            bad = True
        elif e not in color:
            dfs(e, stack + [n])
    color[n] = 2


for n in graph:
    if n not in color:
        dfs(n, [])

for name, fn in mods.items():
    src = open(fn, encoding="utf-8").read()
    top = symtable.symtable(src, fn, "exec")
    defined = {s.get_name() for s in top.get_symbols() if (s.is_assigned() or s.is_imported() or s.is_namespace())}
    defined |= set(dir(builtins)) | {"__name__", "__file__"}

    def walk(t):
        global bad
        for s in t.get_symbols():
            if s.is_global() and s.is_referenced() and s.get_name() not in defined:
                print("UNDEFINED GLOBAL", name, t.get_name(), s.get_name())
                bad = True
        for c in t.get_children():
            walk(c)

    for s in top.get_symbols():
        if s.is_referenced() and s.get_name() not in defined:
            print("UNDEFINED", name, s.get_name())
            bad = True
    for c in top.get_children():
        walk(c)
    for node in ast.walk(ast.parse(src)):
        if isinstance(node, ast.Global):
            print("global in", name, node.names)

tree = ast.parse(open(ROOT + "/__init__.py", encoding="utf-8").read())
for i, node in enumerate(tree.body):
    ok = isinstance(node, (ast.ImportFrom, ast.Import)) or (i == 0 and isinstance(node, ast.Expr)) or (
        isinstance(node, ast.Assign) and node.targets[0].id == "__all__")
    if not ok:
        print("BAD __init__ statement", ast.dump(node)[:100])
        bad = True
print("BAD" if bad else "structure OK", len(mods), "modules")

