tree = ast.parse(open("/tmp/orig/reports_orig.py", encoding="utf-8").read())
names = []
for node in tree.body:
    if isinstance(node, (ast.FunctionDef, ast.ClassDef)):
        names.append(node.name)
    elif isinstance(node, ast.Assign):
        names += [t.id for t in node.targets]
    elif isinstance(node, ast.AnnAssign):
        names.append(node.target.id)
bad = 0
for n in names:
    o = getattr(old, n)
    if n.startswith("_"):
        if hasattr(new, n):
            print("PRIVATE LEAK", n)
            bad += 1
        continue
    if not hasattr(new, n):
        print("MISSING", n)
        bad += 1
        continue
    w = getattr(new, n)
    if inspect.isclass(o):
        ok = inspect.isclass(w) and str(inspect.signature(o)) == str(inspect.signature(w)) and o.__qualname__ == w.__qualname__
        if ok:
            for attr, v in vars(o).items():
                if attr.startswith("__") and attr.endswith("__"):
                    continue
                if inspect.isfunction(v):
                    if str(inspect.signature(v)) != str(inspect.signature(vars(w)[attr])):
                        ok = False
                        print("method sig", n, attr)
            ok = ok and set(vars(o)) == set(vars(w))
    elif inspect.isfunction(o):
        ok = inspect.isfunction(w) and str(inspect.signature(o)) == str(inspect.signature(w)) and o.__doc__ == w.__doc__
    else:
        ok = type(o) == type(w) and o == w
