print("renderer ext:", [(c.name, c.extension, c.__name__) for c in old._RENDERERS.values()] == [(c.name, c.extension, c.__name__) for c in __import__("tally.reports.renderers.base", fromlist=["x"])._RENDERERS.values()])
print("format_money default:", inspect.signature(new.format_money))
print("problems:", bad)

